import 'package:flutter/material.dart'; import 'package:flutter_localizations/flutter_localizations.dart';
import 'screens/home_screen.dart'; import 'screens/timer_screen.dart'; import 'screens/library_screen.dart'; import 'screens/topic_evaluation_screen.dart'; import 'screens/history_screen.dart';
void main()=>runApp(const RahyarApp());
class RahyarApp extends StatelessWidget {const RahyarApp({super.key}); @override Widget build(BuildContext context)=>MaterialApp(title:'رهیار مطالعه',debugShowCheckedModeBanner:false,locale:const Locale('fa'),supportedLocales:const [Locale('fa'),Locale('en')],localizationsDelegates:GlobalMaterialLocalizations.delegates,theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:const Color(0xff176b52),brightness:Brightness.light),scaffoldBackgroundColor:const Color(0xfff5f1e8),fontFamily:'Roboto',appBarTheme:const AppBarTheme(backgroundColor:Color(0xfff5f1e8),centerTitle:false)),home:const AppShell());}
class AppShell extends StatefulWidget{const AppShell({super.key});@override State<AppShell> createState()=>_AppShellState();}
class _AppShellState extends State<AppShell>{int index=0;final pages=const [HomeScreen(),TimerScreen(),LibraryScreen(),TopicEvaluationScreen(),HistoryScreen()];@override Widget build(BuildContext context)=>Scaffold(body:SafeArea(child:IndexedStack(index:index,children:pages)),bottomNavigationBar:NavigationBar(selectedIndex:index,onDestinationSelected:(i)=>setState(()=>index=i),destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'خانه'),NavigationDestination(icon:Icon(Icons.timer_outlined),label:'زمان‌سنج'),NavigationDestination(icon:Icon(Icons.menu_book_outlined),label:'کتابخانه'),NavigationDestination(icon:Icon(Icons.rate_review_outlined),label:'ارزیابی'),NavigationDestination(icon:Icon(Icons.history),label:'تاریخچه')]));}
